				[right, 1229, 392, 0xe6b076],
			]
		],
		oper: [
			[center, 1280, 720, 1184, 151, 1229, 259, 1500], // 回忆
			[center, 1280, 720, 1090, 120, 1121, 154, 1000], // 小
			[center, 1280, 720, 1088, 270, 1123, 305, 1000], // 中
			[center, 1280, 720, 1088, 424, 1126, 461, 1000], // 大
