			operator: [thisOperator[0], thisOperator[1], thisOperator[2], thisOperator[3]
				, thisOperator[11]]
		})) {
			return true;
		}
		if (thisScript.global.shopShare) {
			if (thisScript.oper({
				id: 1110,
				name: '分享',
				operator: [thisOperator[12], thisOperator[7]]
			})) {
				return true;
			}
			if (thisScript.oper({
				id: 1110,
				name: '分享页面',
				operator: [{ desc: thisOperator[9].desc }]
			})) {
