						name: '下一页',
						operator: [thisOperator[6]]
					})) {
						thisScript.regionClick(thisOperator[5].oper);
						thisScript.stop();
						break;
					} else {
						return false;
					}
				} else {
					thisScript.regionSwipe(thisOperator[4].oper[0], thisOperator[4].oper[1], [700, 800], 1000);
				}
				return false;
			}
			sleep(200);
		}
